                    }
                }
            } else if (gitResult.noNewCommit) {
                noCodeChanges = true;
                console.log('ℹ️ No test code changes — skipping PR review, moving ticket directly');
            } else {
                return resetToBacklogAfterGitFailure(ticketKey, gitResult, jiraConfig);
            }
        }

        // Step 5: Post Jira comment
